def transform(grid):
    h, w = len(grid), len(grid[0])
    row_colors = []
    for row in grid:
        row_colors.append(row[0] if all(x == row[0] for x in row) else None)

    known = [(i, c) for i, c in enumerate(row_colors) if c not in (None, 0)]
    if not known:
        return [row[:] for row in grid]

    period = h
    for p in range(1, h + 1):
        pattern = {}
        valid = True
        for i, color in known:
            r = i % p
            if r in pattern and pattern[r] != color:
                valid = False
                break
            pattern[r] = color
        if valid:
            period = p
            break

    out = []
    for i, row in enumerate(grid):
        color = row_colors[i]
        if color == 0 and i % period in pattern:
            color = pattern[i % period]
        if color is None or color == 0:
            out.append(row[:])
        else:
            out.append([color] * w)
    return out
